"use strict";const{describe:describe,it:it,beforeEach:beforeEach}=require("node:test"),assert=require("node:assert/strict");global.window={},global.document={},global.$=()=>({ready:()=>{}});const{renderDealer:renderDealer,ensureHttp:ensureHttp,cfg:cfg}=require("../js/gewa-dealers.js");describe("ensureHttp",(()=>{it("returns # for null",(()=>assert.equal(ensureHttp(null),"#"))),it("returns # for undefined",(()=>assert.equal(ensureHttp(void 0),"#"))),it("returns # for empty string",(()=>assert.equal(ensureHttp(""),"#"))),it("passes through https:// URLs unchanged",(()=>assert.equal(ensureHttp("https://example.com"),"https://example.com"))),it("passes through http:// URLs unchanged",(()=>assert.equal(ensureHttp("http://example.com"),"http://example.com"))),it("prepends https:// to bare domains",(()=>assert.equal(ensureHttp("example.com"),"https://example.com"))),it("is case-insensitive for the protocol check",(()=>assert.equal(ensureHttp("HTTPS://example.com"),"HTTPS://example.com")))})),describe("renderDealer",(()=>{const e={Name:"Test Shop",AddressLine1:"123 Main St",AddressLine2:null,City:"Springfield",StateAbb:"IL",ZipCode:"62701",Phone:"(217) 555-1234",Website:["www.testshop.com"]};beforeEach((()=>{cfg.fields=void 0})),it("wraps output in <address> tags",(()=>{const s=renderDealer(e);assert.ok(s.startsWith("<address>"),"should start with <address>"),assert.ok(s.endsWith("</address>"),"should end with </address>")})),it("includes dealer name in a .dealer-name span",(()=>{const s=renderDealer(e);assert.ok(s.includes('<span class="dealer-name">Test Shop</span>'))})),it("omits name span when Name is missing",(()=>{const s=renderDealer({...e,Name:null});assert.ok(!s.includes("dealer-name"))})),it("includes AddressLine1",(()=>{const s=renderDealer(e);assert.ok(s.includes("123 Main St"))})),it("includes AddressLine2 when present",(()=>{const s=renderDealer({...e,AddressLine2:"Suite 200"});assert.ok(s.includes("Suite 200"))})),it("omits AddressLine2 when null",(()=>{const s=renderDealer({...e,AddressLine2:null});assert.ok(!s.includes("null"))})),it("renders city, state abbreviation, and zip on one line",(()=>{const s=renderDealer(e);assert.ok(s.includes("Springfield, IL 62701"))})),it("formats phone as a tel: link stripping non-digit characters",(()=>{const s=renderDealer(e);assert.ok(s.includes('href="tel:+12175551234"')),assert.ok(s.includes(">(217) 555-1234<"))})),it("renders website URL with https:// prepended",(()=>{const s=renderDealer(e);assert.ok(s.includes('href="https://www.testshop.com"')),assert.ok(s.includes(">www.testshop.com<"))})),it("omits phone when Phone is not in cfg.fields",(()=>{cfg.fields=["Website"];const s=renderDealer(e);assert.ok(!s.includes("tel:"))})),it("omits website when Website is not in cfg.fields",(()=>{cfg.fields=["Phone"];const s=renderDealer(e);assert.ok(!s.includes("www.testshop.com"))})),it("omits website section when Website array is empty",(()=>{const s=renderDealer({...e,Website:[]});assert.ok(!s.includes("testshop"))})),it("skips empty strings inside the Website array",(()=>{const s=renderDealer({...e,Website:["","www.valid.com"]});assert.ok(!s.includes('href="https://"')),assert.ok(s.includes("www.valid.com"))})),it("renders PlusCode in a .plus-code element when present",(()=>{const s=renderDealer({...e,PlusCode:"87C4+RX Springfield"});assert.ok(s.includes("plus-code")),assert.ok(s.includes("87C4+RX Springfield"))})),it("omits PlusCode element when PlusCode is absent",(()=>{const s=renderDealer(e);assert.ok(!s.includes("plus-code"))}))}));